import glob

rows = []
for path in glob.glob("bookings/*.csv"):
    with open(path, encoding="utf-8") as f:
        next(f)
        for line in f:
            rows.append(line.strip().split(","))
rows.sort(key=lambda row: row[0])
for date, guest in rows:
    print(date, guest)
